create table DEVICE
(
    ID         CHARACTER VARYING(50) not null,
    CHILD_ID   CHARACTER VARYING(50),
    NAME       CHARACTER VARYING(255),
    VOLTAGE    CHARACTER VARYING(50),
    TYPE       CHARACTER VARYING(255),
    PATTERN_ID CHARACTER VARYING(255)
);

comment on table DEVICE is '设备信息表';

comment on column DEVICE.ID is '设备Id';

comment on column DEVICE.CHILD_ID is '子设备id';

comment on column DEVICE.NAME is '设备名称';

comment on column DEVICE.VOLTAGE is '电压';

comment on column DEVICE.TYPE is '设备类型';

comment on column DEVICE.PATTERN_ID is '正则id';



create table DEVICE_SCADA_INFO_TYPE
(
    ID                  CHARACTER VARYING(50) not null,
    DEVICE_ID           CHARACTER VARYING(50),
    NAME                CHARACTER VARYING(255),
    UPLOAD              TINYINT,
    MASTER_MERGE        TINYINT,
    PRIORITY            SMALLINT,
    PATTERN_ID          CHARACTER VARYING(255),
    COMMENT             CHARACTER VARYING(255),
    INCLUDE_DEVICE_NAME TINYINT,
    FULL_TEXT_MATCH     TINYINT
);

comment on table DEVICE_SCADA_INFO_TYPE is '设备监控信息类型表';

comment on column DEVICE_SCADA_INFO_TYPE.ID is '校验规则类型id';

comment on column DEVICE_SCADA_INFO_TYPE.DEVICE_ID is '校验规则类型所属设备id';

comment on column DEVICE_SCADA_INFO_TYPE.NAME is '校验规则类型名称';

comment on column DEVICE_SCADA_INFO_TYPE.UPLOAD is '是否上传';

comment on column DEVICE_SCADA_INFO_TYPE.MASTER_MERGE is '是否主站合并';

comment on column DEVICE_SCADA_INFO_TYPE.PRIORITY is '优先级';

comment on column DEVICE_SCADA_INFO_TYPE.PATTERN_ID is '校验规则类型正则id';

comment on column DEVICE_SCADA_INFO_TYPE.COMMENT is '备注';

comment on column DEVICE_SCADA_INFO_TYPE.INCLUDE_DEVICE_NAME is '是否包含设备名';

comment on column DEVICE_SCADA_INFO_TYPE.FULL_TEXT_MATCH is '是否全文匹配';




create table DEVICE_SCADA_INFO_RULE
(
    ID                        CHARACTER VARYING(50) not null,
    DEVICE_SCADA_INFO_TYPE_ID CHARACTER VARYING(50),
    NAME                      CHARACTER VARYING(255),
    RULE                      CHARACTER VARYING(255),
    PATTERN_ID                CHARACTER VARYING(255),
    INCLUDE_DEVICE_NAME       TINYINT,
    FULL_TEXT_MATCH           TINYINT
);

comment on table DEVICE_SCADA_INFO_RULE is '设备监控信息正则表';

comment on column DEVICE_SCADA_INFO_RULE.ID is '校验规则id';

comment on column DEVICE_SCADA_INFO_RULE.DEVICE_SCADA_INFO_TYPE_ID is '校验规则类型Id';

comment on column DEVICE_SCADA_INFO_RULE.NAME is '校验规则名称';

comment on column DEVICE_SCADA_INFO_RULE.RULE is '校验规则';

comment on column DEVICE_SCADA_INFO_RULE.PATTERN_ID is '校验规则正则id';

comment on column DEVICE_SCADA_INFO_RULE.INCLUDE_DEVICE_NAME is '校验时是否包含设备名';

comment on column DEVICE_SCADA_INFO_RULE.FULL_TEXT_MATCH is '是否全文本校验';


create table DEVICE_SCADA_REGEX
(
    ID                CHARACTER VARYING(50) not null,
    PATTERN           CHARACTER VARYING(255),
    NOT_MATCH_MESSAGE CHARACTER VARYING(255)
);

comment on column DEVICE_SCADA_REGEX.ID is '正则id';

comment on column DEVICE_SCADA_REGEX.PATTERN is '正则表达式';

comment on column DEVICE_SCADA_REGEX.NOT_MATCH_MESSAGE is '未匹配时显示信息';

